item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score provides no evidence of variation across runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure whether repeated testing occurred. Stability across runs remains unestablished."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once",
          "reason": "A single run cannot establish stability; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14: No, because repetition was explicitly absent. This leaves stability unknown."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The two-percentage-point range meets the report's stated stability threshold."
        }
      ],
      "instrument_review": "MESA 14: Yes, repeated testing occurred. The observed range also supports stability as defined for this comparison."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers measured scores across repeated runs under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability threshold of two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, because repeated testing occurred, even though its findings contradict stability under the stated definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not supply evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no findings about score variation."
        }
      ],
      "instrument_review": "MESA 14 remains Not sure. Installation guidance is relevant to MESA 22 on reproducibility, but does not establish that repetitions occurred or scores were stable."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish relative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2 identifies a narrow intended use that fits the reported comparison. MESA 20 provides no basis for broader generalization; MESA 25 supports keeping claims within the evaluated puzzles."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on these puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use supplies no additional evidence about performance across domains."
        }
      ],
      "instrument_review": "MESA 2: The intended use is described. MESA 9 and 20: Coverage and evidence for the across-domain claim are insufficient. Under MESA 25, presenting these findings as establishing greater general intelligence would exceed the evidence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone supply no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "MESA 20: The later trial adds evidence beyond initial test scores for correctness in this workshop. MESA 16: The difference interval supports that comparison. MESA 25: Claims should remain limited to correctness under the studied conditions."
    }
  ],
  "closing_note": "No material instruction ambiguity prevented assessment. Labels classify the supplied statements; MESA judgments distinguish whether testing occurred from whether its findings were favourable."
}
